const compare = $input.first().json;
const files = compare.files ?? [];

const relevantFiles = files
  .filter(file => {
    const path = file.filename ?? '';
    const lowerPath = path.toLowerCase();

    // Yalnızca Markdown dosyaları
    if (!lowerPath.endsWith('.md')) return false;

    // Silinen dosyaları işleme alma
    if (file.status === 'removed') return false;

    // BRS kök dizinde, SRS/SDS servis dizinlerinde
    const isSpec =
      path.startsWith('BRS/') ||
      path.includes('/BRS/') ||
      path.includes('/SRS/') ||
      path.includes('/SDS/');

    if (!isSpec) return false;

    // Yardımcı dosyaları hariç tut
    const excluded =
      lowerPath.includes('/input/') ||
      lowerPath.includes('handover') ||
      lowerPath.includes('qareport') ||
      lowerPath.includes('approval-record');

    return !excluded;
  })
  .map(file => {
    const path = file.filename;

    let documentType = null;

    if (path.startsWith('BRS/') || path.includes('/BRS/')) {
      documentType = 'BRS';
    } else if (path.includes('/SRS/')) {
      documentType = 'SRS';
    } else if (path.includes('/SDS/')) {
      documentType = 'SDS';
    }

    return {
      filename: path,
      status: file.status,
      sha: file.sha,
      documentType,
      additions: file.additions ?? 0,
      deletions: file.deletions ?? 0,
      changes: file.changes ?? 0
    };
  });

return [{
  json: {
    baseCommit: compare.base_commit?.sha ?? null,
    currentCommit:
      $('Normalize Commit Info').first().json.currentCommitSha,
    relevantChangeCount: relevantFiles.length,
    hasRelevantChanges: relevantFiles.length > 0,
    relevantFiles
  }
}];

const items = $input.all();
const output = [];

for (const item of items) {
  const file = item.json.relevantFiles;

  if (!file?.filename || !file?.documentType) {
    continue;
  }

  const path = file.filename;
  const documentType = file.documentType.toUpperCase();

  if (!path.toLowerCase().endsWith('.md')) {
    continue;
  }

  if (file.status === 'removed') {
    continue;
  }

  const parts = path.split('/');

  const typeIndex = parts.findIndex(
    part => part.toUpperCase() === documentType
  );

  if (typeIndex === -1) {
    continue;
  }

  // TYPE/<SpecFolder>/<File>.md
  const afterType = parts.slice(typeIndex + 1);

  if (afterType.length !== 2) {
    continue;
  }

  const specFolder = afterType[0];
  const fileName = afterType[1];

  // Normalize: büyük/küçük harf, tire, alt çizgi farklarını kaldır
  const normalize = value =>
    value
      .replace(/\.md$/i, '')
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '');

  const normalizedFolder = normalize(specFolder);
  const normalizedFile = normalize(fileName);

  // Master dosyanın ismi, klasör ismiyle eşleşmeli
  if (normalizedFolder !== normalizedFile) {
    continue;
  }

  output.push({
    json: {
      filename: path,
      fileName,
      specName: specFolder,
      documentType,
      status: file.status,
      sha: file.sha,
      currentCommit: item.json.currentCommit,
      baseCommit: item.json.baseCommit
    }
  });
}

return output;

const results = $input.all();
const config = $('Pipeline Config').first().json;

function getErrorMessage(response) {
  const error = response.error ?? response.message;

  if (typeof error === 'string') return error;
  if (error && typeof error === 'object') {
    return error.message || JSON.stringify(error);
  }

  return 'Upload not confirmed';
}

return results.map((item, index) => {
  // n8n item-linking üzerinden kaynak metadata'yı bul.
  // Loop içindeki item indeksine güvenerek tüm kaynak listesini tarama.
  let source;

  try {
    source = $('Resolve KB Target').itemMatching(index).json;
  } catch (error) {
    throw new Error(
      `Cannot match upload result to source metadata: ${error.message}`
    );
  }

  const response = item.json;

  const requiredFields = [
    'commitId',
    'sourcePath',
    'specName',
    'documentType',
    'kbUrl'
  ];

  const missing = requiredFields.filter(field => !source[field]);

  if (missing.length) {
    throw new Error(
      `Missing metadata: ${missing.join(', ')}`
    );
  }

  const success =
    response.status === 'indexed' &&
    Boolean(response.doc_id);

  return {
    json: {
      pipeline_id: config.repoName,
      commit_id: source.commitId,
      spec_path: source.sourcePath,
      spec_name: source.specName,
      document_type: source.documentType,
      kb_url: source.kbUrl,
      target_version:
        response.version || source.targetVersion || 'v2.14',
      doc_id: response.doc_id || '',
      status: success ? 'SUCCESS' : 'FAILED',
      error_message: success ? '' : getErrorMessage(response),
      processed_at: new Date().toISOString()
    },
    pairedItem: { item: index }
  };
});

const expectedItems = $('Prepare KB Payload').all();
const results = $input.all();

const config = $('Pipeline Config').first().json;
const commitInfo = $('Normalize Commit Info').first().json;

// 1. Expected documents
const expectedDocuments = expectedItems.map(item => ({
  spec_path: item.json.sourcePath,
  document_type: item.json.documentType,
  commit_id: item.json.commitId
}));

const expectedCount = expectedDocuments.length;

// 2. Normalize processed results
const processedDocuments = results.map(item => ({
  spec_path: item.json.spec_path || item.json.sourcePath,
  document_type:
    item.json.document_type || item.json.documentType,
  commit_id:
    item.json.commit_id || item.json.commitId,
  status: String(item.json.status || '').toUpperCase(),
  doc_id: item.json.doc_id || ''
}));

const processedCount = processedDocuments.length;

// 3. Count statuses
const uploadedCount = processedDocuments.filter(
  item => item.status === 'SUCCESS'
).length;

const skippedCount = processedDocuments.filter(
  item => item.status === 'SKIPPED'
).length;

const failedCount = processedDocuments.filter(
  item => !['SUCCESS', 'SKIPPED'].includes(item.status)
).length;

const timeoutCount = processedDocuments.filter(
  item => item.status === 'TIMEOUT'
).length;

// 4. Build document identity keys
const makeKey = item =>
  JSON.stringify([
    item.spec_path,
    item.document_type
  ]);

const expectedKeys = expectedDocuments.map(makeKey);
const processedKeys = processedDocuments.map(makeKey);

const expectedSet = new Set(expectedKeys);
const processedSet = new Set(processedKeys);

// 5. Find missing documents
const missingDocuments = expectedDocuments.filter(
  item => !processedSet.has(makeKey(item))
);

// 6. Find unexpected documents
const unexpectedDocuments = processedDocuments.filter(
  item => !expectedSet.has(makeKey(item))
);

// 7. Find duplicate results
const seen = new Set();

const duplicateDocuments = processedDocuments.filter(item => {
  const key = makeKey(item);

  if (seen.has(key)) {
    return true;
  }

  seen.add(key);
  return false;
});

// 8. Check missing metadata
const invalidDocuments = processedDocuments.filter(
  item =>
    !item.spec_path ||
    !item.document_type ||
    !item.commit_id
);

// 9. Check commit consistency
const commitMismatches = processedDocuments.filter(
  item => {
    const expected = expectedDocuments.find(
      doc => makeKey(doc) === makeKey(item)
    );

    return (
      expected &&
      item.commit_id !== expected.commit_id
    );
  }
);

// 10. Check document IDs for new uploads
const missingDocIds = processedDocuments.filter(
  item =>
    item.status === 'SUCCESS' &&
    !item.doc_id
);

// 11. Final validation
const allSuccessful =
  expectedCount > 0 &&
  processedCount === expectedCount &&
  uploadedCount + skippedCount === expectedCount &&
  failedCount === 0 &&
  expectedSet.size === expectedCount &&
  processedSet.size === expectedCount &&
  missingDocuments.length === 0 &&
  unexpectedDocuments.length === 0 &&
  duplicateDocuments.length === 0 &&
  invalidDocuments.length === 0 &&
  commitMismatches.length === 0 &&
  missingDocIds.length === 0;

// 12. Return summary
return [{
  json: {
    pipelineId: config.repoName,
    currentCommit: commitInfo.currentCommitSha,

    expectedCount,
    processedCount,

    uploadedCount,
    skippedCount,
    failedCount,
    timeoutCount,

    missingDocuments,
    unexpectedDocuments,
    duplicateDocuments,
    invalidDocuments,
    commitMismatches,
    missingDocIds,

    allSuccessful,

    checkedAt: new Date().toISOString()
  }
}];

const config = $('Pipeline Config').first().json;

const kbUrls = {
  BRS: config.brsKbUrl,
  SRS: config.srsKbUrl,
  SDS: config.sdsKbUrl
};

return $input.all().map((item, index) => {
  const data = item.json;
  const type = String(data.documentType || '').toUpperCase();

  const baseUrl = kbUrls[type];

  if (!baseUrl) {
    throw new Error(`KB URL not configured for: ${type}`);
  }

  return {
    json: {
      ...data,
      documentType: type,
      kbUrl: baseUrl.replace(/\/$/, ''),
      uploadUrl:
        `${baseUrl.replace(/\/$/, '')}/api/v1/documents/upload`
    },
    pairedItem: { item: index }
  };
});

const token = $('Get Access Token').first().json.access_token;

if (!token || token.split('.').length !== 3) {
  throw new Error('JWT access token bulunamadı');
}

const payload = token.split('.')[1];
const claims = JSON.parse(
  Buffer.from(payload, 'base64url').toString('utf8')
);

return [{
  json: {
    issuer: claims.iss,
    audience: claims.aud,
    authorizedParty: claims.azp,
    issuedAt: claims.iat
      ? new Date(claims.iat * 1000).toISOString()
      : null,
    expiresAt: claims.exp
      ? new Date(claims.exp * 1000).toISOString()
      : null,
    scope: claims.scope,
    clientRoles: Object.keys(claims.resource_access || {}),
    realmRoles: claims.realm_access?.roles || [],
    expired: claims.exp
      ? Date.now() >= claims.exp * 1000
      : null
  }
}];

const original = $('Edit Fields1').all();

if (original.length !== 1) {
  throw new Error(
    `Expected one item in current loop, got ${original.length}`
  );
}

const item = original[0];

if (!item.binary?.data) {
  throw new Error('Missing binary.data');
}

return [{
  json: item.json,
  binary: item.binary
}];
